@normanmaurer 
I made a java chat client, I do n’t know if there is a better way to disconnect and reconnect; refer to the following example:
![image](https://user-images.githubusercontent.com/22343834/78562462-f7977500-784b-11ea-92f6-60c3e1077587.png)

WebsocketStompClientTest:
public class WebsocketStompClientTest {

    public static void main(String[] args) throws Exception {
        stompClientTest();
    }

    private static void stompClientTest() throws Exception {
        WebSocketClientHandshaker handshaker = WebSocketClientHandshakerFactory.newHandshaker(websocketURI, WebSocketVersion.V13, StompVersion.STOMP_V12.subProtocol(), true, httpHeaders, maxContentLength);
        EventLoopGroup group = new NioEventLoopGroup();
        Bootstrap boot = new Bootstrap();
        boot.option(ChannelOption.SO_KEEPALIVE, true)
                .option(ChannelOption.TCP_NODELAY, true)
                .group(group)
                .handler(new LoggingHandler(LogLevel.INFO))
                .channel(NioSocketChannel.class)
                .handler(new ChannelInitializer<SocketChannel>() {
                    protected void initChannel(SocketChannel socketChannel) throws Exception {
                        ChannelPipeline p = socketChannel.pipeline();
                        p.addLast(new ChannelHandler[]{new HttpClientCodec(), new HttpObjectAggregator(maxContentLength)});
                        p.addLast(new WebSocketClientProtocolHandler(handshaker));
                        p.addLast(new StompClientSubProtocolInitializer(maxContentLength, webSocketChannel -> {
                            //connected send message
                            Thread text = new Thread(new Runnable() {
                                public void run() {
                                    int i = 0;
                                    StompFrame frame = null;
                                    while (i < 5) {
                                        if (i == 0) {
                                            frame = new DefaultStompFrame(StompCommand.CONNECT, Unpooled.copiedBuffer("connect test: " + i, CharsetUtil.UTF_8));
                                            frame.headers()
                                                    .set(ACCEPT_VERSION, StompVersion.STOMP_V12.version())
                                                    .set(HEART_BEAT, "0, 0")
                                                    .set(CONTENT_LENGTH, Integer.toString(frame.content().readableBytes()));
                                        } else if (i == 4) {
                                            frame = new DefaultStompFrame(StompCommand.DISCONNECT, Unpooled.copiedBuffer("delete test: " + i, CharsetUtil.UTF_8));
                                        } else {
                                            frame = new DefaultStompFrame(StompCommand.SEND, Unpooled.copiedBuffer("send test: " + i, CharsetUtil.UTF_8));
                                            frame.headers().set(DESTINATION, "/topic/todoTask/open");
                                            frame.headers().set(CONTENT_LENGTH, Integer.toString(frame.content().readableBytes()));
                                        }
                                        System.out.println("text send " + frame.command() + ": " + i);
                                        webSocketChannel.writeAndFlush(frame).addListener(new ChannelFutureListener() {
                                            public void operationComplete(ChannelFuture channelFuture) throws Exception {
                                                if (channelFuture.isSuccess()) {
                                                    System.out.println("text send success");
                                                } else {
                                                    System.out.println("text send failed  " + channelFuture.cause().getMessage());
                                                }
                                            }
                                        });
                                        try {
                                            Thread.sleep(1000 * 1);
                                        } catch (Exception ex) {

                                        } finally {
                                            i++;
                                        }
                                    }

                                }
                            });
                            text.start();
                        }));
                    }
                });
        boot.connect(websocketURI.getHost(), websocketURI.getPort()).addListener(channelFutureListener).sync();
    }

    static {
        try {
            websocketURI = new URI("ws://localhost:8083/chat");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static URI websocketURI;
    private final static HttpHeaders httpHeaders = new DefaultHttpHeaders();
    private final static Integer maxContentLength = 1024 * 1024 * 64;

    private final static ChannelFutureListener channelFutureListener = new ChannelFutureListener() {

        @Override
        public void operationComplete(ChannelFuture channelFuture) throws Exception {
            if (channelFuture.isSuccess()) {
                // channel = futureListener.channel();
                System.out.println("Connect to server successfully!");
                channelFuture.channel().closeFuture().addListener(future -> {
                    System.out.println("close error");
                    if (future.isSuccess()) {
                        stompClientTest();
                    }
                });
            } else {
                System.out.println("Failed to connect to server, try connect after 10s");
                channelFuture.channel().eventLoop().schedule(() -> {
                    System.out.println("connect error");
                    try {
                        stompClientTest();
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }, 10, TimeUnit.SECONDS);
            }
        }
    };

}
StompClientSubProtocolInitializer:
public class StompClientSubProtocolInitializer extends ChannelInitializer<SocketChannel> {

    private final Consumer<Channel> consumer;
    private final Integer maxContentLength;

    public StompClientSubProtocolInitializer(int maxContentLength, Consumer<Channel> consumer) {
        this.consumer = consumer;
        this.maxContentLength = maxContentLength;
    }

    @Override
    protected void initChannel(SocketChannel channel) throws Exception {
        channel.pipeline().addLast(new MessageToMessageCodec<WebSocketFrame, ByteBuf>() {
            @Override
            public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
                if (evt instanceof WebSocketClientProtocolHandler.ClientHandshakeStateEvent && evt == WebSocketClientProtocolHandler.ClientHandshakeStateEvent.HANDSHAKE_COMPLETE) {
                    ctx.pipeline()
                            .addLast("decoder", new StompSubframeDecoder())
                            .addLast("encoder", new StompSubframeEncoder())
                            .addLast("aggregator", new StompSubframeAggregator(maxContentLength))
                            .addLast("handler", new StompClientHandler());
                    if (consumer != null) {
                        consumer.accept(ctx.channel());
                    }
                } else {
                    super.userEventTriggered(ctx, evt);
                }
            }

            @Override
            protected void encode(ChannelHandlerContext ctx, ByteBuf stompFrame, List<Object> out) {
                out.add(new TextWebSocketFrame(stompFrame.retain()));
            }

            @Override
            protected void decode(ChannelHandlerContext ctx, WebSocketFrame webSocketFrame, List<Object> out) {
                if (webSocketFrame instanceof TextWebSocketFrame) {
                    out.add(webSocketFrame.content().retain());
                } else {
                    ctx.close();
                }
            }

        });
    }
}
StompClientHandler:
public class StompClientHandler extends SimpleChannelInboundHandler<StompFrame> {


    @Override
    protected void channelRead0(ChannelHandlerContext ctx, StompFrame inboundFrame) throws Exception {
        DecoderResult decoderResult = inboundFrame.decoderResult();
        if (decoderResult.isFailure()) {
            System.out.println("error msg: " + decoderResult.toString());
            return;
        }
        System.out.println("test: " + inboundFrame.content().toString());
    }
}
StompVersion: 
public enum StompVersion {

    STOMP_V11("1.1", "v11.stomp"),

    STOMP_V12("1.2", "v12.stomp");

    public static final AttributeKey<StompVersion> CHANNEL_ATTRIBUTE_KEY = AttributeKey.valueOf("stomp_version");
    public static final String SUB_PROTOCOLS;

    static {
        List<String> subProtocols = new ArrayList<String>(values().length);
        for (StompVersion stompVersion : values()) {
            subProtocols.add(stompVersion.subProtocol);
        }

        SUB_PROTOCOLS = StringUtil.join(",", subProtocols).toString();
    }

    private final String version;
    private final String subProtocol;

    StompVersion(String version, String subProtocol) {
        this.version = version;
        this.subProtocol = subProtocol;
    }

    public String version() {
        return version;
    }

    public String subProtocol() {
        return subProtocol;
    }

    public static StompVersion findBySubProtocol(String subProtocol) {
        if (subProtocol != null) {
            for (StompVersion stompVersion : values()) {
                if (stompVersion.subProtocol().equals(subProtocol)) {
                    return stompVersion;
                }
            }
        }
        throw new IllegalArgumentException("Not found StompVersion for '" + subProtocol + "'");
    }
}
